{"Description":"<table hidden aria-hidden="true" role="presentation" class="l9-html-mode"></table>
<!-- HTML 模式识别：保留上面第一行，官网才会保留正常换行；该空表格不会显示。 -->
<!-- 编辑指引：修改下方文字与金额；保留 class、标签、链接和图片地址。 -->

<div class="l9-tnc">

  <!-- 标题区 -->
  <div class="l9-tnc-header">

    <!-- 两侧水晶装饰：保留图片地址与 class -->
    <div aria-hidden="true" class="l9-crystal-layer">
      <img alt="" class="l9-image-crystal left" decoding="async" height="640" src="https://vgbujcuwptvheqijyjbe.supabase.co/storage/v1/object/public/hmac-uploads/projects/f7567eec-beeb-4d83-b1ba-0be127ab8d99/content-assets/legend9-floating-crystal-v1/legend9-floating-crystal-v1.webp" width="640"/>
      <img alt="" class="l9-image-crystal right" decoding="async" height="640" src="https://vgbujcuwptvheqijyjbe.supabase.co/storage/v1/object/public/hmac-uploads/projects/f7567eec-beeb-4d83-b1ba-0be127ab8d99/content-assets/legend9-floating-crystal-v1/legend9-floating-crystal-v1.webp" width="640"/>
    </div>
    <span aria-hidden="true" class="l9-corner tl"></span>
    <span aria-hidden="true" class="l9-corner tr"></span>
    <span aria-hidden="true" class="l9-corner bl"></span>
    <span aria-hidden="true" class="l9-corner br"></span>

    <!-- 活动标题：保留原有 <br> 换行 -->
    <h2 class="l9-tnc-title">New Game Bonus $10<br/>+ Smash 500 pts</h2>

    <!-- 副标题 -->
    <div class="l9-tnc-subtitle">Promotion terms &amp; conditions</div>
  </div>

  <!-- 正文内容 -->
  <div class="l9-tnc-body">
    <div class="l9-original-copy">

      <!-- 奖励要求：01 BONUS REQUIREMENTS -->
      <h3 class="l9-section-title">
        <span class="l9-section-badge"> 01 </span> <strong> BONUS REQUIREMENTS </strong>
      </h3>
      <div aria-label="Promotion requirements table" class="l9-scroll-table" role="region" tabindex="0">

        <!-- 表格：每个 <tr> 为一行，每个 <td> 为一格 -->
        <table class="l9-table l9-icon-table">
          <tbody>
            <tr>
              <td><span> ★ </span></td>
              <td>
                <strong> Bonus 1 </strong> <strong> : </strong> <strong> $10 </strong> <strong> Free credit (All members) </strong>
              </td>
            </tr>
            <tr>
              <td><span> ★ </span></td>
              <td><strong> Bonus 2 </strong> <strong> : 500 smash points (New members) </strong></td>
            </tr>
            <tr>
              <td><span> ★ </span></td>
              <td><strong> Selected New Game Only </strong></td>
            </tr>
            <tr>
              <td><span> ★ </span></td>
              <td>
                PG SOFT / EVOPLAY / PETER &amp; SONS / BONZA / THUNDERKICK / RUBYPLAY / NOLIMIT / HACKSAW / YGGDRASIL / DREAMTECH / POPIPLAY / MASCOT / POPOK / TADA / XGAMING / AVATAR / FUNTA
              </td>
            </tr>
            <tr>
              <td>✘</td>
              <td>No Save Free Game</td>
            </tr>
          </tbody>
        </table>
      </div>
      <strong>Click Button Below</strong>
      <a class="white-btn" href="#" onclick="promopage(5); return false;">
        <span class="icon"> ⭐️ </span> <span class="blink-text"> Free Smash Points </span> <span class="icon"> ⭐️ </span>
      </a>

      <!-- 提款要求：02 WITHDRAW REQUIREMENTS -->
      <h3 class="l9-section-title">
        <span class="l9-section-badge"> 02 </span> <strong> WITHDRAW REQUIREMENTS </strong>
      </h3>
      <p><strong> BONUS 1 </strong></p>

      <!-- 提款重点卡片 -->
      <div class="l9-withdraw-grid">
        <div class="l9-rule-card">
          <span class="l9-req-label"> ✵ Winover </span> <span class="l9-req-val"> $299 </span>
        </div>
        <div class="l9-rule-card">
          <span class="l9-req-label"> ✵ Max Withdrawal </span> <span class="l9-req-val"> $20 </span>
        </div>
      </div>
      <p><strong> BONUS 2 </strong></p>

      <!-- 提款重点卡片 -->
      <div class="l9-withdraw-grid">
        <div class="l9-rule-card">
          <span class="l9-req-label"> ✵ Winover </span> <span class="l9-req-val"> x3 (Based on Bonus) </span>
        </div>
        <div class="l9-rule-card">
          <span class="l9-req-label"> ✵ Max Withdrawal </span> <span class="l9-req-val"> x5 (Based on Bonus) </span>
        </div>
      </div>

      <!-- 活动条款：03 TERM AND CONDITION -->
      <h3 class="l9-section-title">
        <span class="l9-section-badge"> 03 </span> <strong> TERM AND CONDITION </strong>
      </h3>
      <p><span> ✪ </span> Register name must same as bank.</p>
      <p><span> ✪ </span> Cant combined deposit, free credit, rebate &amp; commission..</p>
      <p><span> ✪ </span> All credit will be forfeited subject to any violation of rules</p>
      <p class="l9-legal-copy">Legend9 general terms &amp; conditions apply.</p>
      <p class="l9-legal-copy">
        If found illegal betting, abnormal betting situation, bonus hunting, side betting, save free game inside game &amp; deposit to withdraw, we shall freeze the deposit (including the amount of the profit and bonus), the system will automatically clear the balance to zero (0).
      </p>

      <!-- 认证与付款图片：保留原图、原色及比例 -->
      <img class="l9-footer-img" src="https://static.gwvkyk.com/media/fddc348b4a2a6c12f5d7c.png"/>

      <!-- 版权文字 -->
      <p class="l9-copyright">Copyright © 2026 Legend-9. All Rights Reserved.</p>
    </div>
  </div>

  <!-- 底部水晶装饰：原生 Close / Claim 按钮由平台保留 -->
  <img alt="" aria-hidden="true" class="l9-floating-shard" decoding="async" height="640" src="https://vgbujcuwptvheqijyjbe.supabase.co/storage/v1/object/public/hmac-uploads/projects/f7567eec-beeb-4d83-b1ba-0be127ab8d99/content-assets/legend9-floating-crystal-v1/legend9-floating-crystal-v1.webp" width="640"/>
</div>

<!-- 设计样式区：通常无需修改；已限定于 Legend9 T&C 弹窗。 -->
<style>
#promotion-popup:has(.l9-tnc) {
   --l9-content: #120c18;
   --l9-panel: #211329;
   --l9-text: #fff7fc;
   --l9-text-sec: #d5bed4;
   --l9-champagne: #f5d78d;
   position: relative;
   width: min(720px, calc(100vw - 24px)) !important;
   max-width: 100%;
   padding: 0 !important;
   background: #120c18 !important;
   color: var(--l9-text);
   border: 1px solid #ff1493;
   border-radius: 16px 4px 16px 4px;
   box-shadow: inset 0 0 0 3px #120c18, inset 0 0 0 4px #784269, 0 15px 28px #0007;
   overflow: hidden;
   font-family: Arial, sans-serif;
   font-size: 13px;
   line-height: 1.6;
   text-transform: none;

}
 #promotion-popup:has(.l9-tnc) > .title, #promotion-popup:has(.l9-tnc) > p {
   display: none;

}
 #promotion-popup:has(.l9-tnc) var {
   font: inherit;
   color: inherit;
   text-transform: none;

}
 #promotion-popup .l9-tnc, #promotion-popup .l9-tnc * {
   box-sizing: border-box;

}
 #promotion-popup .l9-tnc {
   text-align: left;

}
 #promotion-popup .l9-tnc .l9-tnc-header {
   position: relative;
   padding: 28px 110px 22px;
   text-align: center;
   border-bottom: 1px solid #f5d78d;
   background: radial-gradient(ellipse at 50% 0%, #ff80c817, transparent 65%), linear-gradient(135deg, #ff80c813 0 15%, transparent 15% 85%, #ff80c810 85%), linear-gradient(45deg, #78426955 0 13%, transparent 13% 87%, #78426944 87%), linear-gradient(#341240, #211329);
   box-shadow: inset 0 0 0 4px #120c18, inset 0 0 0 5px #784269, inset 0 6px 0 #f5d78d28, 0 3px 0 #09060d;

}
 #promotion-popup .l9-tnc .l9-tnc-header::before {
   content: "";
   position: absolute;
   inset: 7px;
   background: repeating-linear-gradient(45deg, transparent 0 30px, #f5d78d12 30px 31px, transparent 31px 61px), repeating-linear-gradient(-45deg, transparent 0 30px, #ff80c813 30px 31px, transparent 31px 61px);
   opacity: .45;
   mask-image: linear-gradient(90deg, #000, transparent 35% 65%, #000);
   pointer-events: none;

}
 #promotion-popup .l9-tnc .l9-tnc-header::after {
   content: "✦";
   position: absolute;
   bottom: -12px;
   left: calc(50% - 27px);
   width: 54px;
   color: #f5d78d;
   background: linear-gradient(90deg, #211329, #341240, #211329);
   font-size: 17px;
   line-height: 23px;
   text-shadow: 0 1px 0 #a86e27;
   border-radius: 0 0 10px 10px;

}
 #promotion-popup .l9-tnc .l9-tnc-title {
   position: relative;
   z-index: 3;
   margin: 0;
   font-size: 30px;
   font-weight: 700;
   line-height: 1.2;
   color: #f5d78d;
   text-shadow: 0 2px 1px #211221;
   overflow-wrap: anywhere;

}
 #promotion-popup .l9-tnc .l9-tnc-subtitle {
   position: relative;
   z-index: 3;
   display: inline-block;
   margin-top: 8px;
   padding: 4px 12px;
   border: 1px solid #784269;
   border-radius: 12px;
   background: #301739;
   color: #d5bed4;
   font-size: 11px;
   letter-spacing: 1px;
   text-transform: uppercase;
   box-shadow: inset 0 1px 0 #ff80c830, 0 2px 0 #120c18;

}
 #promotion-popup .l9-tnc .l9-crystal-layer {
   position: absolute;
   inset: 0;
   overflow: hidden;
   z-index: 2;
   pointer-events: none;

}
 #promotion-popup .l9-tnc .l9-image-crystal {
   position: absolute;
   display: block;
   max-width: none;
   object-fit: contain;
   filter: saturate(.8) contrast(.88);
   opacity: .85;
   pointer-events: none;

}
 #promotion-popup .l9-tnc .l9-image-crystal.left {
   width: 132px;
   height: 132px;
   left: -12px;
   top: 13px;
   transform: rotate(-12deg);

}
 #promotion-popup .l9-tnc .l9-image-crystal.right {
   width: 320px;
   height: 320px;
   right: -124px;
   top: 12px;
   transform: rotate(10deg);

}
 #promotion-popup .l9-tnc .l9-corner {
   position: absolute;
   width: 28px;
   height: 20px;
   top: 10px;
   left: 10px;
   border-top: 2px solid #f5d78d;
   border-left: 2px solid #a86e27;
   box-shadow: -1px -1px 0 #09060d;
   z-index: 1;
   pointer-events: none;

}
 #promotion-popup .l9-tnc .l9-corner::after {
   content: "";
   position: absolute;
   width: 4px;
   height: 4px;
   top: -3px;
   left: 25px;
   background: #f5d78d;
   transform: rotate(45deg);

}
 #promotion-popup .l9-tnc .l9-corner.tr {
   left: auto;
   right: 10px;
   transform: scaleX(-1);

}
 #promotion-popup .l9-tnc .l9-corner.bl {
   top: auto;
   bottom: 10px;
   transform: scaleY(-1);

}
 #promotion-popup .l9-tnc .l9-corner.br {
   top: auto;
   left: auto;
   bottom: 10px;
   right: 10px;
   transform: scale(-1);

}
 #promotion-popup .l9-tnc .l9-tnc-body {
   padding: 20px 24px 0;
   background: #120c18;

}
 #promotion-popup .l9-tnc .l9-section-title {
   display: flex;
   align-items: center;
   gap: 8px;
   margin: 24px 0 12px;
   color: #f5d78d;
   font-size: 15px;
   font-weight: 700;
   line-height: 1.4;

}
 #promotion-popup .l9-tnc .l9-section-title:first-child {
   margin-top: 8px;

}
 #promotion-popup .l9-tnc .l9-section-title::after {
   content: "";
   flex: 1;
   min-width: 8px;
   height: 7px;
   margin-left: 2px;
   background: linear-gradient(90deg, #a86e2780, transparent) left center / 100% 1px no-repeat;

}
 #promotion-popup .l9-tnc .l9-section-badge {
   flex: 0 0 auto;
   padding: 5px 6px 7px;
   font-size: 11px;
   color: #fff7fc;
   border: 1px solid #ff80c8;
   border-radius: 2px;
   background: linear-gradient(135deg, #ff80c8, #ff1493 40%, #784269);
   clip-path: polygon(0 0, 100% 0, 100% 78%, 50% 100%, 0 78%);
   box-shadow: inset 0 2px 0 #fff7fc66, inset -2px -2px 0 #341240;

}
 #promotion-popup .l9-tnc .l9-deposit-image {
   display: block;
   width: 100%;
   height: auto;
   margin: 0;
   border-radius: 4px;

}
 #promotion-popup .l9-tnc .l9-table {
   width: 100%;
   border-collapse: collapse;
   margin: 12px 0;
   font-size: 13px;
   border: 1px solid #784269;
   background: transparent;

}
 #promotion-popup .l9-tnc .l9-table td {
   padding: 9px 12px;
   border-bottom: 1px solid #301739;
   text-align: left;
   color: #fff7fc;
   background: transparent;
   overflow-wrap: anywhere;

}
 #promotion-popup .l9-tnc .l9-table td:first-child {
   width: 30px;
   color: #f5d78d;

}
 #promotion-popup .l9-tnc .l9-table tr:nth-child(even) td {
   background: #211329;

}
 #promotion-popup .l9-tnc .l9-highlight {
   color: #f5d78d;
   font-weight: 700;

}
 #promotion-popup .l9-tnc .l9-req-grid {
   display: flex;
   gap: 12px;
   margin-bottom: 18px;

}
 #promotion-popup .l9-tnc .l9-req-card {
   position: relative;
   flex: 1;
   min-width: 0;
   padding: 18px 16px;
   text-align: center;
   border: 1px solid #784269;
   border-radius: 12px 2px 12px 2px;
   background: radial-gradient(ellipse at 0 0, #78426940, transparent 60%), linear-gradient(135deg, #301739, #211329 70%);
   box-shadow: inset 0 0 0 3px #120c18, inset 0 0 0 4px #784269, 0 3px 0 #09060d;

}
 #promotion-popup .l9-tnc .l9-req-card::before {
   content: "";
   position: absolute;
   top: 10px;
   left: 10px;
   width: 8px;
   height: 8px;
   background: conic-gradient(#fff7fc, #ff80c8, #ff1493, #341240, #ff80c8, #fff7fc);
   transform: rotate(45deg);
   border: 1px solid #f5d78d;
   pointer-events: none;

}
 #promotion-popup .l9-tnc .l9-req-card::after {
   content: "";
   position: absolute;
   inset: 6px;
   border: 1px solid #f5d78d;
   border-radius: 8px 1px 8px 1px;
   opacity: .3;
   pointer-events: none;

}
 #promotion-popup .l9-tnc .l9-req-label {
   color: #d5bed4;
   font-size: 12px;

}
 #promotion-popup .l9-tnc .l9-req-val {
   color: #f5d78d;
   font-size: 20px;
   font-weight: 700;
   line-height: 1.35;

}
 #promotion-popup .l9-tnc .l9-req-note {
   color: #d5bed4;
   font-size: 12px;

}
 #promotion-popup .l9-tnc .l9-terms {
   margin: 0;
   padding-left: 20px;
   color: #d5bed4;
   list-style: decimal;

}
