{"Description":"<var><p>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>BNG9</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600&display=swap');
body{
font-family:'Poppins',sans-serif;
background:#121212;
color:#fff;
padding:10px;
margin:0;
}
.promo-table{
width:100%;
border-collapse:separate;
border-spacing:0;
background:#1E1E1E;
border-radius:8px;
overflow:hidden;
box-shadow:0 5px 15px rgba(0,0,0,0.3);
font-size:13px;
margin-bottom:20px;
}
.promo-table th{
background:linear-gradient(to right, #00E7F8, #4FE38F);
color:#000;
padding:10px 5px;
text-align:center;
font-weight:600;
text-transform:uppercase;
letter-spacing:0.5px;
font-size:12px;
}
.promo-table td{
padding:10px 15px;
border-bottom:1px solid #2D2D2D;
}
.promo-table tr:last-child td{border-bottom:none;}
.promo-table tr:nth-child(even){background-color:#252525;}
.promo-table tr:hover{background-color:#2D2D2D;}
.badge{
display:inline-block;
padding:3px 8px;
border-radius:10px;
font-size:11px;
font-weight:600;
text-transform:uppercase;
letter-spacing:0.5px;
}
.badge-primary{
background:rgba(0,231,248,0.15);
color:#00E7F8;
border:1px solid #00E7F8;
}
.badge-highlight{
background:linear-gradient(to right, #00E7F8, #4FE38F);
color:#000;
}
.badge-rollover{
background:rgba(255,255,255,0.1);
color:#b9ff96;
border:1px solid #b9ff96;
}
.main-blink-me{
animation:blink 1.5s infinite;
font-weight:700;
}
@keyframes blink{
0%{opacity:1;}
50%{opacity:0.7;}
100%{opacity:1;}
}
.tc-link{
color:#00E7F8;
text-decoration:none;
font-weight:500;
transition:all 0.2s;
}
.tc-link:hover{text-decoration:underline;}
.app-download{
display:inline-block;
background:linear-gradient(to right, #00E7F8, #4FE38F);
color:#000000;
padding:5px 10px;
border-radius:15px;
text-decoration:none;
font-weight:600;
border:1px solid #00E7F8;
margin-top:3px;
transition:all 0.2s;
font-size:11px;
}
.app-download:hover{
background:linear-gradient(to right, #00F5FF, #66F0A5);
color:#000;
}
.warning{
color:#00E7F8;
}
.separator-line{
border-top:1px solid #2D2D2D;
margin:15px 0;
}
</style>
<table class="promo-table">
<thead>
<tr>
<th colspan="2">NEW SIGN-UP FREE CREDIT</th>
</tr>
</thead>
<tbody>
<tr>
<td width="40%"><strong>Free Credit</strong></td>
<td><span class="main-blink-me">FREE $19</span> For New Players</td>
</tr>
<tr>
<td><strong>Withdraw Requirement</strong></td>
<td><span class="badge badge-rollover">Hit 200 Credit</span></td>
</tr>
<tr>
<td><strong>Max Withdraw</strong></td>
<td><span class="badge badge-highlight">$20</span></td>
</tr>
<tr>
<td><strong>Claim Limit</strong></td>
<td>1 Claim Per Lifetime</td>
</tr>
<tr>
<td><strong>Game Restrictions</strong></td>
<td>All Pokies</td>
</tr>
<tr>
<td><strong>Please Note</strong></td>
<td>
<span class="warning">❌</span> Cannot Mixing With Deposit / Rebate<br>
<span class="warning">❌</span> Save Free Games
</tr>
<tr>
<td><strong>Account Policy</strong></td>
<td>1 Account • 1 IP • 1 Device</td>
</tr>
<tr>
<td><strong>Violation Warning</strong></td>
<td><span class="warning">⚠️</span> Don’t Break The Rules — Your Credit Won’t Stay</td>
</tr>
<tr>
<td><strong>Mobile App Only</strong></td>
<td>
<a href="https://www.bng9auh5api.shop/uploads/appwrap.html" class="app-download">DOWNLOAD NOW</a>
</td>
</tr>
</tbody>
</table>
<hr class="separator-line">
<p style="font-size:10px;color:#bbb;">BNG9 General Terms & Conditions apply.</p>
<p style="font-size:10px;color:#bbb;">If any irregular or suspicious betting activity is detected — including bonus hunting, side betting, or using tricks to save free games (scatters) to clear turnover before depositing — BNG9 reserves the right to cancel all winnings, freeze or forfeit any balance, and suspend or deactivate the account without prior notice.</p>
<p style="font-size:10px;color:#bbb;">Please note that all promotions and bonuses may be changed, modified, suspended, or terminated at any time without notice.</p>
<p style="font-size:10px;color:#bbb;">By participating in any BNG9 promotion, members agree to accept and comply with all terms stated above and all related rules listed on our official website.</p>
<p style="font-size:10px;color:#bbb;">© 2025 BNG9. All rights reserved.</p></var>","DescQuillEditor":{"ops":[{"insert":"
"}]},"DescQuillHTML":""}

