<div class="premium-green-promo"><style>.premium-green-promo,.premium-green-promo *{box-sizing:border-box}.premium-green-promo{--green:#00e69a;--bright-green:#56ffae;--gold:#e6c77a;--white:#f2fff8;--border:rgba(58,214,141,.28);width:100%;max-width:900px;margin:0 auto;padding:18px;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:1.6;color:var(--white);background:radial-gradient(circle at 100% 0%,rgba(0,194,110,.17),transparent 40%),linear-gradient(145deg,#092c20,#04150f 75%);border:1px solid rgba(65,221,145,.45);border-radius:18px;box-shadow:0 8px 28px rgba(0,0,0,.2);overflow:hidden}.premium-green-promo .promo-header{text-align:center;padding:17px 12px;margin-bottom:16px;background:linear-gradient(120deg,#064b32,#0b7049,#064b32);border:1px solid rgba(230,199,122,.45);border-radius:12px}.premium-green-promo .promo-header h2{margin:0;color:var(--gold);font-size:20px;font-weight:800;letter-spacing:.5px;line-height:1.4}.premium-green-promo .promo-section{margin-bottom:22px}.premium-green-promo .promo-section:last-child{margin-bottom:0}.premium-green-promo .promo-list{border:1px solid var(--border);border-radius:12px;overflow:hidden;background:rgba(6,51,33,.8)}.premium-green-promo .promo-item{display:flex;align-items:flex-start;gap:12px;padding:14px;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.premium-green-promo .promo-item:last-child{border-bottom:0}.premium-green-promo .promo-item:nth-child(even){background:rgba(22,105,66,.2)}.premium-green-promo .promo-icon{flex:0 0 26px;width:26px;height:26px;display:flex;justify-content:center;align-items:center;border-radius:7px;background:rgba(0,230,154,.12);border:1px solid rgba(0,230,154,.35);color:var(--bright-green);font-size:14px;font-weight:bold}.premium-green-promo .promo-icon.danger{background:rgba(255,74,74,.1);border-color:rgba(255,74,74,.35);color:#ff6565}.premium-green-promo .promo-content{flex:1;min-width:0;color:var(--white);font-size:13px;font-weight:600;line-height:1.7}.premium-green-promo .highlight{color:var(--bright-green);font-weight:800}.premium-green-promo .highlight-gold{color:var(--gold);font-weight:800}.premium-green-promo .danger-text{color:#ff7979;font-weight:800}.premium-green-promo .promo-terms{padding:5px 14px;background:rgba(6,51,33,.8);border:1px solid var(--border);border-radius:12px}.premium-green-promo .term-row{display:flex;align-items:flex-start;gap:11px;padding:13px 0;border-bottom:1px solid var(--border);color:var(--white);font-size:13px;font-weight:600}.premium-green-promo .term-row:last-child{border-bottom:none}.premium-green-promo .term-star{color:#ff6b6b;font-size:17px;font-weight:bold;line-height:1.3}@media(max-width:600px){.premium-green-promo{padding:10px;border-radius:12px;font-size:12px}.premium-green-promo .promo-header{padding:13px 8px;margin-bottom:12px}.premium-green-promo .promo-header h2{font-size:17px}.premium-green-promo .promo-item{padding:11px 9px;gap:9px}.premium-green-promo .promo-content,.premium-green-promo .term-row{font-size:12px}.premium-green-promo .promo-section{margin-bottom:16px}.premium-green-promo .promo-section:last-child{margin-bottom:0}}</style><section class="promo-section"><div class="promo-header"><h2>Bonus Requirements</h2></div><div class="promo-list"><div class="promo-item"><span class="promo-icon">✓</span><div class="promo-content">Daily Free <span class="highlight">AUD 5</span></div></div><div class="promo-item"><span class="promo-icon">✓</span><div class="promo-content">Daily claim <span class="highlight"> x1 Time</span></div></div><div class="promo-item"><span class="promo-icon">✓</span><div class="promo-content">Limited Claim <span class="highlight">ONE(1)</span> Per Player Only</div></div></div></section><section class="promo-section"><div class="promo-header"><h2>Withdraw Requirements</h2></div><div class="promo-list"><div class="promo-item"><span class="promo-icon">✓</span><div class="promo-content">Credit Reach <span class="highlight-gold">$150</span> To Unlock Withdraw</div></div><div class="promo-item"><span class="promo-icon">✓</span><div class="promo-content">Maximum Withdraw <span class="highlight">AUD10 ( Will Convert into Redeposit Bonus )</span></div></div><div class="promo-item"><span class="promo-icon">✓</span><div class="promo-content">Only available for <span class="highlight">EVENT slot</span></div></div><div class="promo-item"><span class="promo-icon danger">✕</span><div class="promo-content danger-text">SAVE FREE SPIN丨SAVE BONUS丨BUY FREE</div></div></div></section><section class="promo-section"><div class="promo-header"><h2>Terms &amp; Conditions</h2></div><div class="promo-terms"><div class="term-row"><span class="term-star">*</span><span>Change Bank Account Upon Withdraw Is Not Allowed.</span></div><div class="term-row"><span class="term-star">*</span><span>Can't Have Multiple Accounts With The Same IP.</span></div><div class="term-row"><span class="term-star">*</span><span>Register Name Need To Match Bank Account Full Name.</span></div><div class="term-row"><span class="term-star">*</span><span>If Break Rules All Credit Will Forfeit.</span></div></div></section></div>

